import re

def check_accessibility(html: str) -> list:
    issues = []

    # img-alt check
    img_tags = re.finditer(r'<img\b([^>]*)/?>', html, re.IGNORECASE)
    for match in img_tags:
        attrs = match.group(1)
        if 'alt=' not in attrs and 'alt =' not in attrs:
            issues.append({'rule': 'img-alt', 'element': 'img', 'message': 'Image missing alt attribute', 'severity': 'error'})

    # button-text check
    button_matches = re.finditer(r'<button\b[^>]*>(.*?)</button>', html, re.IGNORECASE | re.DOTALL)
    for match in button_matches:
        content = match.group(1).strip()
        content_text = re.sub(r'<[^>]+>', '', content).strip()
        if not content_text:
            issues.append({'rule': 'button-text', 'element': 'button', 'message': 'Button has no text content', 'severity': 'error'})

    # input-label check
    input_tags = re.finditer(r'<input\b([^>]*)/?>', html, re.IGNORECASE)
    for match in input_tags:
        attrs = match.group(1)
        if 'type="hidden"' in attrs or "type='hidden'" in attrs:
            continue
        if 'aria-label' not in attrs:
            id_match = re.search(r'id=["\']([^"\']*)["\']', attrs)
            if id_match:
                input_id = id_match.group(1)
                if f'for="{input_id}"' not in html and f"for='{input_id}'" not in html:
                    issues.append({'rule': 'input-label', 'element': 'input', 'message': 'Input missing associated label or aria-label', 'severity': 'error'})
            else:
                issues.append({'rule': 'input-label', 'element': 'input', 'message': 'Input missing associated label or aria-label', 'severity': 'error'})

    # heading-order check
    headings = re.findall(r'<(h[1-6])\b', html, re.IGNORECASE)
    last_level = 0
    for h in headings:
        level = int(h[1])
        if last_level > 0 and level > last_level + 1:
            issues.append({'rule': 'heading-order', 'element': h.lower(), 'message': f'Heading level skipped: h{last_level} to h{level}', 'severity': 'error'})
        last_level = level

    # link-text check
    generic_texts = {'click here', 'here', 'read more', 'more', 'link'}
    link_matches = re.finditer(r'<a\b[^>]*>(.*?)</a>', html, re.IGNORECASE | re.DOTALL)
    for match in link_matches:
        text = re.sub(r'<[^>]+>', '', match.group(1)).strip().lower()
        if text in generic_texts:
            issues.append({'rule': 'link-text', 'element': 'a', 'message': f'Link has generic text: {text}', 'severity': 'warning'})

    # lang-attr check
    html_tag = re.search(r'<html\b([^>]*)>', html, re.IGNORECASE)
    if html_tag:
        if 'lang=' not in html_tag.group(1):
            issues.append({'rule': 'lang-attr', 'element': 'html', 'message': 'html element missing lang attribute', 'severity': 'error'})

    return issues

