function checkAccessibility(html) {
  const issues = [];

  // img-alt
  const imgRegex = /<img\b([^>]*)\/?>/gi;
  let m;
  while ((m = imgRegex.exec(html)) !== null) {
    if (!m[1].includes('alt=')) {
      issues.push({ rule: 'img-alt', element: 'img', message: 'Image missing alt attribute', severity: 'error' });
    }
  }

  // button-text
  const btnRegex = /<button\b[^>]*>(.*?)<\/button>/gis;
  while ((m = btnRegex.exec(html)) !== null) {
    const text = m[1].replace(/<[^>]+>/g, '').trim();
    if (!text) {
      issues.push({ rule: 'button-text', element: 'button', message: 'Button has no text content', severity: 'error' });
    }
  }

  // input-label
  const inputRegex = /<input\b([^>]*)\/?>/gi;
  while ((m = inputRegex.exec(html)) !== null) {
    const attrs = m[1];
    if (/type=["']hidden["']/i.test(attrs)) continue;
    if (!attrs.includes('aria-label')) {
      const idMatch = attrs.match(/id=["']([^"']*)["']/);
      if (!idMatch || (!html.includes(`for="${idMatch[1]}"`) && !html.includes(`for='${idMatch[1]}'`))) {
        issues.push({ rule: 'input-label', element: 'input', message: 'Input missing associated label or aria-label', severity: 'error' });
      }
    }
  }

  // heading-order
  const headings = [...html.matchAll(/<(h[1-6])\b/gi)];
  let lastLevel = 0;
  for (const h of headings) {
    const level = parseInt(h[1][1]);
    if (lastLevel > 0 && level > lastLevel + 1) {
      issues.push({ rule: 'heading-order', element: h[1].toLowerCase(), message: `Heading level skipped: h${lastLevel} to h${level}`, severity: 'error' });
    }
    lastLevel = level;
  }

  // link-text
  const genericTexts = new Set(['click here', 'here', 'read more', 'more', 'link']);
  const linkRegex = /<a\b[^>]*>(.*?)<\/a>/gis;
  while ((m = linkRegex.exec(html)) !== null) {
    const text = m[1].replace(/<[^>]+>/g, '').trim().toLowerCase();
    if (genericTexts.has(text)) {
      issues.push({ rule: 'link-text', element: 'a', message: `Link has generic text: ${text}`, severity: 'warning' });
    }
  }

  // lang-attr
  const htmlTag = html.match(/<html\b([^>]*)>/i);
  if (htmlTag && !htmlTag[1].includes('lang=')) {
    issues.push({ rule: 'lang-attr', element: 'html', message: 'html element missing lang attribute', severity: 'error' });
  }

  return issues;
}
